"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { Mail, Rss } from "lucide-react";
import { Github, Linkedin } from "@/components/icons";
import { profile } from "@/lib/profile";
import { useView } from "@/components/view-context";

const VISIT_CACHE_KEY = "anvilry:visits:total";

/**
 * Fire-and-forget visitor counter. POSTs to /api/visit on mount (once per page load),
 * then shows the running total. Rate-limited server-side to 1 increment per IP / 30 min.
 * Gate: NEXT_PUBLIC_VISITOR_COUNTER=true (default OFF).
 *
 * localStorage fallback: seeds from cache on mount so repeat visitors see the last-known
 * count instantly, and so the badge shows a real number when Redis is unavailable (total=0).
 * Only a positive total from the API overwrites the cache — a 0 (Redis down) is ignored.
 */
function VisitorBadge() {
  // Always start with null — localStorage is browser-only and must not be read during SSR.
  // Reading it in the useState initializer causes a hydration mismatch because the server
  // renders null→skeleton while the client renders cached count→real badge.
  // Seed from localStorage in useEffect (client-only, post-hydration) instead.
  const [total, setTotal] = useState<number | null>(null);

  useEffect(() => {
    // Seed from localStorage cache so repeat visitors see the last-known count
    // before the API call resolves. This setState call is intentional and safe:
    // it runs once on mount (client-only) and does not depend on any external
    // subscription — it is a one-time initialisation from a local store, which is
    // a documented exception to the set-state-in-effect heuristic.
    try {
      const cached = localStorage.getItem(VISIT_CACHE_KEY);
      if (cached !== null) setTotal(Number(cached)); // eslint-disable-line react-hooks/set-state-in-effect -- intentional: one-time localStorage seed on mount, no subscription
    } catch {
      // localStorage unavailable — stay on null (skeleton shown)
    }

    fetch("/api/visit", { method: "POST" })
      .then((r) => (r.ok ? r.json() : null))
      .then((data: { total: number; today: number } | null) => {
        if (data?.total != null && data.total > 0) {
          setTotal(data.total);
          try {
            localStorage.setItem(VISIT_CACHE_KEY, String(data.total));
          } catch {
            // localStorage blocked (private browsing / storage full) — ignore
          }
        }
        // If total === 0: Redis was unavailable. Keep the cached value (don't call setTotal).
      })
      .catch(() => {
        // Network error — cached value (already in state) stays visible
      });
  }, []);

  if (total === null) {
    return (
      <span
        className="inline-block h-3 w-28 animate-pulse rounded bg-fg-subtle/20"
        aria-hidden="true"
      />
    );
  }
  if (total === 0) return null; // No cache, no real count — hide the badge entirely

  return (
    <span className="font-mono text-xs text-fg-subtle">
      ↑ {total.toLocaleString()} engineers visited
    </span>
  );
}

// Machine-readable surfaces — the AI-crawler / agent-native artifacts. Grouped here so
// they're discoverable (previously /llms.txt + /api/resume.json existed but weren't
// linked from anywhere). On-brand for a GenAI engineer.
const MACHINE_LINKS = [
  { href: "/mcp", label: "MCP server" },
  { href: "/llms.txt", label: "llms.txt" },
  { href: "/api/resume.json", label: "resume.json" },
];

// Views whose <main> fills the full viewport below the nav (h-[calc(100dvh-3.5rem)]) —
// a global marketing footer underneath them has nowhere to go but past the fold, where it
// converges with / overlaps the immersive console on short viewports. Hidden there; the
// document-flow Classic and Play views keep it. Client-gated, so Classic (the SSG default)
// still ships the footer in its prerendered HTML for crawlers — it only hides post-hydration
// when a full-height view is active.
const FULL_HEIGHT_VIEWS = new Set(["chat", "developer"]);

export function SiteFooter() {
  const showVisitorCounter = process.env.NEXT_PUBLIC_VISITOR_COUNTER === "true";
  const { view } = useView();
  if (FULL_HEIGHT_VIEWS.has(view)) return null;

  return (
    <footer className="mt-auto border-t border-border/60">
      <div className="mx-auto flex w-full max-w-5xl flex-col items-start justify-between gap-6 px-6 py-10 sm:flex-row sm:items-center">
        <div>
          <p className="font-mono text-sm">
            <span className="text-accent">{profile.name}</span>
          </p>
          <p className="mt-1 text-xs text-fg-subtle">
            {profile.role} · {profile.location}
          </p>
          {showVisitorCounter && (
            <p className="mt-2">
              <VisitorBadge />
            </p>
          )}
        </div>

        <div className="flex flex-col items-start gap-4 sm:items-end">
          {/* For AI agents — the machine-readable links. */}
          <nav
            aria-label="Machine-readable"
            className="flex items-center gap-4 text-xs text-fg-subtle"
          >
            <span className="font-mono">{"// for AI:"}</span>
            {MACHINE_LINKS.map((l) => (
              <Link
                key={l.href}
                href={l.href}
                className="font-mono hover:text-accent"
              >
                {l.label}
              </Link>
            ))}
          </nav>

          <div className="flex items-center gap-5 text-fg-muted">
            <a
              href={profile.links.github}
              target="_blank"
              rel="noopener noreferrer"
              className="hover:text-accent"
              aria-label="GitHub"
            >
              <Github size={18} />
            </a>
            <a
              href={profile.links.linkedin}
              target="_blank"
              rel="noopener noreferrer"
              className="hover:text-accent"
              aria-label="LinkedIn"
            >
              <Linkedin size={18} />
            </a>
            <a
              href={`mailto:${profile.email}`}
              className="hover:text-accent"
              aria-label="Email"
            >
              <Mail size={18} />
            </a>
          </div>
        </div>
      </div>

      {/* Copyright + RSS + newsletter — full-width bottom strip */}
      <div className="mx-auto flex w-full max-w-5xl flex-wrap items-center justify-between gap-3 border-t border-border/40 px-6 pb-6 pt-4 font-mono text-[11px] text-fg-subtle">
        {/* Build-time year, not a render-time `new Date()`. Under cacheComponents an in-render
            new Date() fails the prerender as an "unstable value" (and this footer is on nearly
            every route, so it broke /, /articles and /resume). NEXT_PUBLIC_BUILD_YEAR is computed
            in next.config.ts at build time and inlined, so it is stable AND refreshes per deploy.
            Fallback keeps local/test renders sane if the env var is ever absent. */}
        <span>
          © {process.env.NEXT_PUBLIC_BUILD_YEAR ?? "2026"} Sairam Ugge
        </span>
        <div className="flex items-center gap-4">
          <a
            href={profile.substackUrl}
            target="_blank"
            rel="noopener noreferrer"
            className="transition-colors hover:text-accent"
          >
            Subscribe
          </a>
          <a
            href="/feed.xml"
            className="inline-flex items-center gap-1 transition-colors hover:text-accent"
          >
            <Rss size={11} aria-hidden="true" /> RSS
          </a>
        </div>
      </div>
    </footer>
  );
}

