const SCREENSHOT_DIR = path.join(__dirname, "verification_screenshots");
if (!fs.existsSync(SCREENSHOT_DIR)) {
  fs.mkdirSync(SCREENSHOT_DIR, { recursive: true });
}

async function run() {
  const browser = await chromium.launch({ headless: true });
  console.log("=== STARTING BROWSER VERIFICATION ===");

  // -------------------------------------------------------------
  // 1. Mobile (390px) - /work page (screenshot 1 scenario)
  // -------------------------------------------------------------
  console.log("\n1. Testing /work on 390px mobile viewport...");
  const mobileContext = await browser.newContext({
    viewport: { width: 390, height: 844 },
    deviceScaleFactor: 2,
  });
  const mobileWorkPage = await mobileContext.newPage();
  await mobileWorkPage.goto("http://localhost:3000/work", { waitUntil: "networkidle" });
  console.log("  Waiting 8s to test if 'Try a different view' hint appears...");
  await mobileWorkPage.waitForTimeout(8000);

  const mobileHintVisible = await mobileWorkPage.locator('text="Try a different view"').isVisible();
  console.log(`  'Try a different view' visible on /work (390px): ${mobileHintVisible} (Expected: false)`);
  if (mobileHintVisible) {
    throw new Error("FAILED: ViewHint should NOT appear on /work!");
  }
  const workHeadingVisible = await mobileWorkPage.locator('text="Systems I helped build"').isVisible();
  console.log(`  Heading 'Systems I helped build' visible: ${workHeadingVisible}`);

  const shot1 = path.join(SCREENSHOT_DIR, "1_work_page_390px_after_fix.png");
  await mobileWorkPage.screenshot({ path: shot1 });
  console.log(`  Screenshot saved: ${shot1}`);
  await mobileWorkPage.close();
  await mobileContext.close();

  // -------------------------------------------------------------
  // 2. Desktop (1440px) - /projects page (screenshot 2 scenario)
  // -------------------------------------------------------------
  console.log("\n2. Testing /projects on 1440px desktop viewport...");
  const desktopContext = await browser.newContext({
    viewport: { width: 1440, height: 900 },
    deviceScaleFactor: 1,
  });
  const desktopProjectsPage = await desktopContext.newPage();
  await desktopProjectsPage.goto("http://localhost:3000/projects", { waitUntil: "networkidle" });
  console.log("  Waiting 8s to test if 'Try a different view' hint appears...");
  await desktopProjectsPage.waitForTimeout(8000);

  const desktopHintVisible = await desktopProjectsPage.locator('text="Try a different view"').isVisible();
  console.log(`  'Try a different view' visible on /projects (1440px): ${desktopHintVisible} (Expected: false)`);
  if (desktopHintVisible) {
    throw new Error("FAILED: ViewHint should NOT appear on /projects!");
  }

  const shot2 = path.join(SCREENSHOT_DIR, "2_projects_page_1440px_after_fix.png");
  await desktopProjectsPage.screenshot({ path: shot2 });
  console.log(`  Screenshot saved: ${shot2}`);
  await desktopProjectsPage.close();
  await desktopContext.close();

  // -------------------------------------------------------------
  // 3. Desktop (1440px) - Home page (hint SHOULD appear here)
  // -------------------------------------------------------------
  console.log("\n3. Testing home page '/' on desktop (hint SHOULD appear)...");
  const homeContext = await browser.newContext({
    viewport: { width: 1440, height: 900 },
    deviceScaleFactor: 1,
  });
  const homePage = await homeContext.newPage();
  await homePage.goto("http://localhost:3000/", { waitUntil: "networkidle" });
  console.log("  Before 7s delay: checking hint is NOT visible yet...");
  let homeHintBefore = await homePage.locator('text="Try a different view"').isVisible();
  console.log(`  Hint before delay: ${homeHintBefore} (Expected: false)`);

  console.log("  Waiting for 7s dwell delay...");
  await homePage.waitForTimeout(7500);

  let homeHintAfter = await homePage.locator('text="Try a different view"').isVisible();
  console.log(`  Hint after delay: ${homeHintAfter} (Expected: true)`);
  if (!homeHintAfter) {
    throw new Error("FAILED: ViewHint SHOULD appear on home page after dwell delay!");
  }

  const shotHome = path.join(SCREENSHOT_DIR, "home_hint_visible_1440px.png");
  await homePage.screenshot({ path: shotHome });
  console.log(`  Screenshot saved: ${shotHome}`);
  await homePage.close();
  await homeContext.close();

  // -------------------------------------------------------------
  // 4. Footer Visitor Counter - First visit, Redis unavailable (total=0)
  // (Screenshot 3 scenario)
  // -------------------------------------------------------------
  console.log("\n4. Testing footer visitor counter: First visit with Redis unavailable...");
  const firstVisitContext = await browser.newContext({
    viewport: { width: 1440, height: 900 },
  });
  const firstVisitPage = await firstVisitContext.newPage();
  await firstVisitPage.goto("http://localhost:3000/about", { waitUntil: "networkidle" });

  console.log("  Waiting 2s for /api/visit response and state update...");
  await firstVisitPage.waitForTimeout(2000);

  // Check footer content
  const footerElement = firstVisitPage.locator("footer");
  const footerText = await footerElement.innerText();
  const pulseSkeletonCount = await footerElement.locator(".animate-pulse").count();
  const engineersVisitedVisible = await footerElement.locator('text="engineers visited"').isVisible();

  console.log(`  Pulse skeleton count in footer: ${pulseSkeletonCount} (Expected: 0)`);
  console.log(`  Engineers visited text visible: ${engineersVisitedVisible} (Expected: false)`);

  if (pulseSkeletonCount !== 0) {
    throw new Error("FAILED: Pulse skeleton is still visible! It should be removed.");
  }
  if (engineersVisitedVisible) {
    throw new Error("FAILED: Count should NOT be shown when total is 0 and no cache.");
  }

  const shot3 = path.join(SCREENSHOT_DIR, "3_footer_first_visit_after_fix_1440px.png");
  await footerElement.screenshot({ path: shot3 });
  console.log(`  Footer screenshot saved: ${shot3}`);
  await firstVisitPage.close();
  await firstVisitContext.close();

  // -------------------------------------------------------------
  // 5. Footer Visitor Counter - Returning visitor, Redis unavailable
  // -------------------------------------------------------------
  console.log("\n5. Testing footer visitor counter: Returning visitor with cached count...");
  const returningContext = await browser.newContext({
    viewport: { width: 1440, height: 900 },
  });
  const returningPage = await returningContext.newPage();
  // Pre-seed localStorage before navigating
  await returningPage.addInitScript(() => {
    localStorage.setItem("anvilry:visits:total", "2480");
  });
  await returningPage.goto("http://localhost:3000/about", { waitUntil: "networkidle" });
  await returningPage.waitForTimeout(2000);

  const returningFooter = returningPage.locator("footer");
  const returningCountText = await returningFooter.locator('text="↑ 2,480 engineers visited"').isVisible();
  console.log(`  Returning visitor sees cached count '↑ 2,480 engineers visited': ${returningCountText} (Expected: true)`);
  if (!returningCountText) {
    throw new Error("FAILED: Returning visitor should see cached count!");
  }

  const returningStoredValue = await returningPage.evaluate(() => localStorage.getItem("anvilry:visits:total"));
  console.log(`  localStorage value after API call: ${returningStoredValue} (Expected: '2480')`);
  if (returningStoredValue !== "2480") {
    throw new Error("FAILED: Cached count should not be overwritten by 0!");
  }

  const shot4 = path.join(SCREENSHOT_DIR, "4_footer_returning_cached_count_1440px.png");
  await returningFooter.screenshot({ path: shot4 });
  console.log(`  Footer screenshot saved: ${shot4}`);
  await returningPage.close();
  await returningContext.close();

  // -------------------------------------------------------------
  // 6. Footer Visitor Counter - Real API count returned (> 0)
  // -------------------------------------------------------------
  console.log("\n6. Testing footer visitor counter: Real API count returned (3,150)...");
  const realApiContext = await browser.newContext({
    viewport: { width: 1440, height: 900 },
  });
  const realApiPage = await realApiContext.newPage();
  // Route /api/visit to return a mock real count
  await realApiPage.route("**/api/visit", async (route) => {
    await route.fulfill({
      status: 200,
      contentType: "application/json",
      body: JSON.stringify({ total: 3150, today: 45 }),
    });
  });

  await realApiPage.goto("http://localhost:3000/about", { waitUntil: "networkidle" });
  await realApiPage.waitForTimeout(1000);

  const realApiFooter = realApiPage.locator("footer");
  const realApiCountVisible = await realApiFooter.locator('text="↑ 3,150 engineers visited"').isVisible();
  console.log(`  Real API count '↑ 3,150 engineers visited' visible: ${realApiCountVisible} (Expected: true)`);
  if (!realApiCountVisible) {
    throw new Error("FAILED: Real count should be displayed!");
  }

  const realApiStoredValue = await realApiPage.evaluate(() => localStorage.getItem("anvilry:visits:total"));
  console.log(`  localStorage updated to: ${realApiStoredValue} (Expected: '3150')`);
  if (realApiStoredValue !== "3150") {
    throw new Error("FAILED: Real count should be remembered in localStorage!");
  }

  const shot5 = path.join(SCREENSHOT_DIR, "5_footer_real_api_count_1440px.png");
  await realApiFooter.screenshot({ path: shot5 });
  console.log(`  Footer screenshot saved: ${shot5}`);
  await realApiPage.close();
  await realApiContext.close();

  // -------------------------------------------------------------
  // 7. Footer Visitor Counter - Network Error / API Failure
  // -------------------------------------------------------------
  console.log("\n7. Testing footer visitor counter: Network failure...");
  const errorContext = await browser.newContext({
    viewport: { width: 1440, height: 900 },
  });
  const errorPage = await errorContext.newPage();
  await errorPage.route("**/api/visit", async (route) => {
    await route.abort("failed");
  });

  await errorPage.goto("http://localhost:3000/about", { waitUntil: "networkidle" });
  await errorPage.waitForTimeout(1000);

  const errorFooter = errorPage.locator("footer");
  const errorPulseCount = await errorFooter.locator(".animate-pulse").count();
  const errorTextVisible = await errorFooter.locator('text="engineers visited"').isVisible();
  console.log(`  On network failure (first visit), pulse skeleton count: ${errorPulseCount} (Expected: 0)`);
  console.log(`  On network failure (first visit), count visible: ${errorTextVisible} (Expected: false)`);
  if (errorPulseCount !== 0 || errorTextVisible) {
    throw new Error("FAILED: On network failure for first-time visitor, nothing should be shown and skeleton should not be stuck!");
  }
  await errorPage.close();
  await errorContext.close();

  console.log("\n=== ALL BROWSER VERIFICATIONS PASSED SUCCESSFULLY! ===");
  await browser.close();
}

run().catch((err) => {
  console.error("Verification failed:", err);
  process.exit(1);
});

